import{_ as e,c as d,o,b2 as a}from"./chunks/framework.CUhoHPxN.js";const m=JSON.parse('{"title":"系统配置模块（部门 / 字典 / 参数 / 公告）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/backend/modules/system-management.md","filePath":"docs/backend/modules/system-management.md"}'),c={name:"docs/backend/modules/system-management.md"};function r(l,t,i,s,h,n){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="系统配置模块-部门-字典-参数-公告" tabindex="-1">系统配置模块（部门 / 字典 / 参数 / 公告） <a class="header-anchor vp-link" href="#系统配置模块-部门-字典-参数-公告" aria-label="Permalink to &quot;系统配置模块（部门 / 字典 / 参数 / 公告）&quot;">​</a></h1><h2 id="部门管理" tabindex="-1">部门管理 <a class="header-anchor vp-link" href="#部门管理" aria-label="Permalink to &quot;部门管理&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>Controller</td><td><code>SysDeptController</code></td></tr><tr><td>路径</td><td><code>/system/dept</code></td></tr><tr><td>前端</td><td><code>views/system/dept/</code></td></tr></tbody></table></div><div class="vp-table"><table><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td>GET <code>/list</code></td><td>部门列表（树形）</td></tr><tr><td>GET <code>/treeselect</code></td><td>下拉树</td></tr><tr><td>GET <code>/{deptId}</code></td><td>详情</td></tr><tr><td>POST <code>/update</code></td><td>新增/修改</td></tr><tr><td>POST <code>/remove/{deptId}</code></td><td>删除</td></tr></tbody></table></div><p>用户、数据权限依赖部门树；列表页常用 <code>handleTree</code> 与 <code>C7TreeSelect</code>。</p><hr><h2 id="字典管理" tabindex="-1">字典管理 <a class="header-anchor vp-link" href="#字典管理" aria-label="Permalink to &quot;字典管理&quot;">​</a></h2><h3 id="字典类型" tabindex="-1">字典类型 <a class="header-anchor vp-link" href="#字典类型" aria-label="Permalink to &quot;字典类型&quot;">​</a></h3><p>| 路径 | <code>/system/dict/type</code> | | 前端 | <code>views/system/dict/type/index.vue</code> |</p><p>主要接口：<code>/list</code>、<code>/{dictId}</code>、<code>/update</code>、<code>/remove/{dictId}</code>、<code>/export</code>、<code>/refresh</code>、<code>/import</code>。</p><h3 id="字典数据" tabindex="-1">字典数据 <a class="header-anchor vp-link" href="#字典数据" aria-label="Permalink to &quot;字典数据&quot;">​</a></h3><p>| 路径 | <code>/system/dict/data</code> | | 前端 | <code>views/system/dict/data/index.vue</code> |</p><ul><li><code>GET /type/{dictType}</code>：按类型取字典项（前端 <code>useDict</code> 缓存）</li><li>支持导入导出、模板下载</li></ul><p>前端展示：<code>C7DictTag</code>、表格列 <code>columnType: &#39;tag&#39;</code>。</p><hr><h2 id="参数配置" tabindex="-1">参数配置 <a class="header-anchor vp-link" href="#参数配置" aria-label="Permalink to &quot;参数配置&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>Controller</td><td><code>SysConfigController</code></td></tr><tr><td>路径</td><td><code>/system/config</code></td></tr><tr><td>前端</td><td><code>views/system/config/index.vue</code>（<strong>列表页模板参考</strong>）</td></tr></tbody></table></div><div class="vp-table"><table><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td>GET <code>/list</code></td><td>分页</td></tr><tr><td>GET <code>/{configId}</code>、<code>/configKey/{configKey}</code></td><td>按 ID 或 key 查询</td></tr><tr><td>POST <code>/create</code>、<code>/update</code>、<code>/remove</code></td><td>CRUD</td></tr><tr><td>POST <code>/refreshCache</code></td><td>刷新参数缓存</td></tr><tr><td>POST <code>/export</code></td><td>导出</td></tr></tbody></table></div><p>系统内置参数（如代码生成开关）由 Flyway 种子数据写入。</p><hr><h2 id="通知公告" tabindex="-1">通知公告 <a class="header-anchor vp-link" href="#通知公告" aria-label="Permalink to &quot;通知公告&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>Controller</td><td><code>SysNoticeController</code></td></tr><tr><td>路径</td><td><code>/system/notice</code></td></tr><tr><td>前端</td><td><code>views/system/notice/index.vue</code></td></tr></tbody></table></div><div class="vp-table"><table><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td>GET <code>/list</code>、<code>/{noticeId}</code></td><td>查询</td></tr><tr><td>POST <code>/create</code>、<code>/update</code>、<code>/remove</code></td><td>维护</td></tr></tbody></table></div><p>富文本内容经 <strong>OWASP HTML Sanitizer</strong> 过滤后存储，防 XSS。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor vp-link" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../../frontend/list-page-template.html" class="vp-link">前端列表页模板</a></li><li><a href="./../api/system.html" class="vp-link">系统接口</a></li></ul>',26)])])}const b=e(c,[["render",r]]);export{m as __pageData,b as default};
